def run(ctx):
    """从任务队列里取队首任务；队列空了就用目标兜底。"""
    tasks = ctx.state.get('tasks') or []
    if isinstance(tasks, str):
        tasks = [t.strip() for t in tasks.splitlines() if t.strip()]
    current = tasks[0] if tasks else ctx.text
    ctx.state['tasks'] = tasks[1:]
    ctx.state['current_task'] = current
    ctx.emit('task', {'remaining': len(ctx.state['tasks']), 'current': current[:80]})
    return {'data': current}

